package shiraz.runtime;
public final class NativeText {
    static { System.loadLibrary("shiraz-text"); }
    private NativeText() { }
    public static float measure(String text, float size) { return measureFont(text, size, "sans-serif", 0); }
    public static float measureFont(String text,float size,String family,int style){return measureVariable(text,size,family,style,null,null,0);}
    public static float measureVariable(String text,float size,String family,int style,int[] tags,float[] values,float spacing){return measureResolved(text,size,family,style,tags,values,spacing,null);}
    public static float measureResolved(String text,float size,String family,int style,int[] tags,float[] values,float spacing,byte[] levels){return measureResolved(text,size,family,style,tags,values,spacing,null,levels);}
    public static native float measureResolved(String text,float size,String family,int style,int[] tags,float[] values,float spacing,String featureSettings,byte[] levels);
    public static float[] clusters(String text,float size,String family,int style,int[] tags,float[] values,float spacing){return clustersResolved(text,size,family,style,tags,values,spacing,null);}
    public static float[] clustersResolved(String text,float size,String family,int style,int[] tags,float[] values,float spacing,byte[] levels){return clustersResolved(text,size,family,style,tags,values,spacing,null,levels);}
    public static native float[] clustersResolved(String text,float size,String family,int style,int[] tags,float[] values,float spacing,String featureSettings,byte[] levels);
    public static int breakVariable(String text,float size,String family,int style,int[] tags,float[] values,float spacing,boolean forwards,float maxWidth,float[] measuredWidth){return breakResolved(text,size,family,style,tags,values,spacing,forwards,maxWidth,measuredWidth,null);}
    public static int breakResolved(String text,float size,String family,int style,int[] tags,float[] values,float spacing,boolean forwards,float maxWidth,float[] measuredWidth,byte[] levels){return breakResolved(text,size,family,style,tags,values,spacing,null,forwards,maxWidth,measuredWidth,levels);}
    public static native int breakResolved(String text,float size,String family,int style,int[] tags,float[] values,float spacing,String featureSettings,boolean forwards,float maxWidth,float[] measuredWidth,byte[] levels);
    public static float[] metrics(float size) { return metricsFont(size, "sans-serif", 0); }
    public static float[] metricsFont(float size,String family,int style){return metricsVariable(size,family,style,null,null);}
    public static native float[] metricsVariable(float size,String family,int style,int[] tags,float[] values);
    public static int[] boundsVariable(String text,float size,String family,int style,int[] tags,float[] values,float spacing,boolean fakeBold,float skew,int hinting,float scaleX){return boundsResolved(text,size,family,style,tags,values,spacing,fakeBold,skew,hinting,scaleX,null);}
    public static int[] boundsResolved(String text,float size,String family,int style,int[] tags,float[] values,float spacing,boolean fakeBold,float skew,int hinting,float scaleX,byte[] levels){return boundsResolved(text,size,family,style,tags,values,spacing,null,fakeBold,skew,hinting,scaleX,levels);}
    public static native int[] boundsResolved(String text,float size,String family,int style,int[] tags,float[] values,float spacing,String featureSettings,boolean fakeBold,float skew,int hinting,float scaleX,byte[] levels);
    public static native int[] variationAxes(String family,int style);
    public static void draw(int[] pixels, int width, int height, String text, float x, float y, float size, int color, boolean antialias) {
        drawFont(pixels, width, height, text, x, y, size, color, antialias, "sans-serif", 0);
    }
    public static void drawFont(int[] pixels, int width, int height, String text, float x, float y, float size, int color, boolean antialias, String family, int style) {
        drawFontClipped(pixels,width,height,text,x,y,size,color,antialias,family,style,0,0,width,height);
    }
    public static void drawFontClipped(int[] pixels,int width,int height,String text,float x,float y,float size,int color,boolean antialias,String family,int style,int left,int top,int right,int bottom) {
        drawFontClippedStyled(pixels,width,height,text,x,y,size,color,antialias,family,style,left,top,right,bottom,false);
    }
    public static void drawFontClippedStyled(int[] pixels,int width,int height,String text,float x,float y,float size,int color,boolean antialias,String family,int style,int left,int top,int right,int bottom,boolean fakeBold){drawFontClippedSkewed(pixels,width,height,text,x,y,size,color,antialias,family,style,left,top,right,bottom,fakeBold,0);}
    public static void drawFontClippedSkewed(int[] pixels,int width,int height,String text,float x,float y,float size,int color,boolean antialias,String family,int style,int left,int top,int right,int bottom,boolean fakeBold,float skew){drawVariable(pixels,width,height,text,x,y,size,color,antialias,family,style,left,top,right,bottom,fakeBold,skew,null,null,0);}
    public static void drawVariable(int[] pixels,int width,int height,String text,float x,float y,float size,int color,boolean antialias,String family,int style,int left,int top,int right,int bottom,boolean fakeBold,float skew,int[] tags,float[] values,float spacing){drawPaint(pixels,width,height,text,x,y,size,color,antialias,family,style,left,top,right,bottom,fakeBold,skew,tags,values,spacing,0,0,0,0,4);}
    public static void drawPaint(int[] pixels,int width,int height,String text,float x,float y,float size,int color,boolean antialias,String family,int style,int left,int top,int right,int bottom,boolean fakeBold,float skew,int[] tags,float[] values,float spacing,int paintStyle,float strokeWidth,int cap,int join,float miter){drawHinted(pixels,width,height,text,x,y,size,color,antialias,family,style,left,top,right,bottom,fakeBold,skew,tags,values,spacing,paintStyle,strokeWidth,cap,join,miter,1);}
    public static void drawHinted(int[] pixels,int width,int height,String text,float x,float y,float size,int color,boolean antialias,String family,int style,int left,int top,int right,int bottom,boolean fakeBold,float skew,int[] tags,float[] values,float spacing,int paintStyle,float strokeWidth,int cap,int join,float miter,int hinting){drawScaled(pixels,width,height,text,x,y,size,color,antialias,family,style,left,top,right,bottom,fakeBold,skew,tags,values,spacing,paintStyle,strokeWidth,cap,join,miter,hinting,1);}
    public static void drawScaled(int[] pixels,int width,int height,String text,float x,float y,float size,int color,boolean antialias,String family,int style,int left,int top,int right,int bottom,boolean fakeBold,float skew,int[] tags,float[] values,float spacing,int paintStyle,float strokeWidth,int cap,int join,float miter,int hinting,float scaleX){drawResolved(pixels,width,height,text,x,y,size,color,antialias,family,style,left,top,right,bottom,fakeBold,skew,tags,values,spacing,paintStyle,strokeWidth,cap,join,miter,hinting,scaleX,null);}
    public static void drawResolved(int[] pixels,int width,int height,String text,float x,float y,float size,int color,boolean antialias,String family,int style,int left,int top,int right,int bottom,boolean fakeBold,float skew,int[] tags,float[] values,float spacing,int paintStyle,float strokeWidth,int cap,int join,float miter,int hinting,float scaleX,byte[] levels){drawResolved(pixels,width,height,text,x,y,size,color,antialias,family,style,left,top,right,bottom,fakeBold,skew,tags,values,spacing,null,paintStyle,strokeWidth,cap,join,miter,hinting,scaleX,levels);}
    public static native void drawResolved(int[] pixels,int width,int height,String text,float x,float y,float size,int color,boolean antialias,String family,int style,int left,int top,int right,int bottom,boolean fakeBold,float skew,int[] tags,float[] values,float spacing,String featureSettings,int paintStyle,float strokeWidth,int cap,int join,float miter,int hinting,float scaleX,byte[] levels);
    public static void drawPathResolved(int[] pixels,int width,int height,String text,float x,float y,float size,int color,boolean antialias,String family,int style,int left,int top,int right,int bottom,boolean fakeBold,float skew,int[] tags,float[] values,float spacing,int paintStyle,float strokeWidth,int cap,int join,float miter,int hinting,float scaleX,byte[] levels,android.graphics.PathMeasure measure,float[] matrix){drawPathResolved(pixels,width,height,text,x,y,size,color,antialias,family,style,left,top,right,bottom,fakeBold,skew,tags,values,spacing,null,paintStyle,strokeWidth,cap,join,miter,hinting,scaleX,levels,measure,matrix);}
    public static native void drawPathResolved(int[] pixels,int width,int height,String text,float x,float y,float size,int color,boolean antialias,String family,int style,int left,int top,int right,int bottom,boolean fakeBold,float skew,int[] tags,float[] values,float spacing,String featureSettings,int paintStyle,float strokeWidth,int cap,int join,float miter,int hinting,float scaleX,byte[] levels,android.graphics.PathMeasure measure,float[] matrix);
    public static void drawAffineResolved(int[] pixels,int width,int height,String text,float x,float y,float size,int color,boolean antialias,String family,int style,int left,int top,int right,int bottom,boolean fakeBold,float skew,int[] tags,float[] values,float spacing,int paintStyle,float strokeWidth,int cap,int join,float miter,int hinting,float scaleX,byte[] levels,float[] matrix){drawAffineResolved(pixels,width,height,text,x,y,size,color,antialias,family,style,left,top,right,bottom,fakeBold,skew,tags,values,spacing,null,paintStyle,strokeWidth,cap,join,miter,hinting,scaleX,levels,matrix);}
    public static native void drawAffineResolved(int[] pixels,int width,int height,String text,float x,float y,float size,int color,boolean antialias,String family,int style,int left,int top,int right,int bottom,boolean fakeBold,float skew,int[] tags,float[] values,float spacing,String featureSettings,int paintStyle,float strokeWidth,int cap,int join,float miter,int hinting,float scaleX,byte[] levels,float[] matrix);
    public static int[] boundsSubpixelResolved(String text,float size,String family,int style,int[] tags,float[] values,float spacing,boolean fakeBold,float skew,int hinting,float scaleX,byte[] levels,boolean subpixel){return boundsSubpixelResolved(text,size,family,style,tags,values,spacing,null,fakeBold,skew,hinting,scaleX,levels,subpixel);}
    public static native int[] boundsSubpixelResolved(String text,float size,String family,int style,int[] tags,float[] values,float spacing,String featureSettings,boolean fakeBold,float skew,int hinting,float scaleX,byte[] levels,boolean subpixel);
    public static void drawSubpixelResolved(int[] pixels,int width,int height,String text,float x,float y,float size,int color,boolean antialias,String family,int style,int left,int top,int right,int bottom,boolean fakeBold,float skew,int[] tags,float[] values,float spacing,int paintStyle,float strokeWidth,int cap,int join,float miter,int hinting,float scaleX,byte[] levels,boolean subpixel){drawSubpixelResolved(pixels,width,height,text,x,y,size,color,antialias,family,style,left,top,right,bottom,fakeBold,skew,tags,values,spacing,null,paintStyle,strokeWidth,cap,join,miter,hinting,scaleX,levels,subpixel);}
    public static native void drawSubpixelResolved(int[] pixels,int width,int height,String text,float x,float y,float size,int color,boolean antialias,String family,int style,int left,int top,int right,int bottom,boolean fakeBold,float skew,int[] tags,float[] values,float spacing,String featureSettings,int paintStyle,float strokeWidth,int cap,int join,float miter,int hinting,float scaleX,byte[] levels,boolean subpixel);
    public static void drawPathSubpixelResolved(int[] pixels,int width,int height,String text,float x,float y,float size,int color,boolean antialias,String family,int style,int left,int top,int right,int bottom,boolean fakeBold,float skew,int[] tags,float[] values,float spacing,int paintStyle,float strokeWidth,int cap,int join,float miter,int hinting,float scaleX,byte[] levels,android.graphics.PathMeasure measure,float[] matrix,boolean subpixel){drawPathSubpixelResolved(pixels,width,height,text,x,y,size,color,antialias,family,style,left,top,right,bottom,fakeBold,skew,tags,values,spacing,null,paintStyle,strokeWidth,cap,join,miter,hinting,scaleX,levels,measure,matrix,subpixel);}
    public static native void drawPathSubpixelResolved(int[] pixels,int width,int height,String text,float x,float y,float size,int color,boolean antialias,String family,int style,int left,int top,int right,int bottom,boolean fakeBold,float skew,int[] tags,float[] values,float spacing,String featureSettings,int paintStyle,float strokeWidth,int cap,int join,float miter,int hinting,float scaleX,byte[] levels,android.graphics.PathMeasure measure,float[] matrix,boolean subpixel);
    public static void drawAffineSubpixelResolved(int[] pixels,int width,int height,String text,float x,float y,float size,int color,boolean antialias,String family,int style,int left,int top,int right,int bottom,boolean fakeBold,float skew,int[] tags,float[] values,float spacing,int paintStyle,float strokeWidth,int cap,int join,float miter,int hinting,float scaleX,byte[] levels,float[] matrix,boolean subpixel){drawAffineSubpixelResolved(pixels,width,height,text,x,y,size,color,antialias,family,style,left,top,right,bottom,fakeBold,skew,tags,values,spacing,null,paintStyle,strokeWidth,cap,join,miter,hinting,scaleX,levels,matrix,subpixel);}
    public static native void drawAffineSubpixelResolved(int[] pixels,int width,int height,String text,float x,float y,float size,int color,boolean antialias,String family,int style,int left,int top,int right,int bottom,boolean fakeBold,float skew,int[] tags,float[] values,float spacing,String featureSettings,int paintStyle,float strokeWidth,int cap,int join,float miter,int hinting,float scaleX,byte[] levels,float[] matrix,boolean subpixel);
}
